"""Private reference review; only the report is written to the agent workspace."""
import json
import os
from pathlib import Path

REPO = Path(os.environ.get("BENCH_REPO_ROOT", "/app/repo"))
APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPORT = json.loads("{\"schema_version\":2,\"reviews\":[{\"candidate\":\"cedar\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":125,\"quantity\":3},{\"unit_cents\":7,\"quantity\":2}],\"member\":true},\"expected\":{\"total_cents\":350}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false},\"expected\":{\"total_cents\":10000}},{\"input\":{\"lines\":[],\"member\":true},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":0,\"quantity\":7}],\"member\":true},\"expected\":{\"total_cents\":0}}]},{\"candidate\":\"maple\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/maple/checkout.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":125,\"quantity\":3},{\"unit_cents\":7,\"quantity\":2}],\"member\":true},\"expected\":{\"total_cents\":350}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false},\"expected\":{\"total_cents\":10000}},{\"input\":{\"lines\":[],\"member\":true},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":0,\"quantity\":7}],\"member\":true},\"expected\":{\"total_cents\":0}}]},{\"candidate\":\"birch\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/birch/checkout.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":125,\"quantity\":3},{\"unit_cents\":7,\"quantity\":2}],\"member\":true},\"expected\":{\"total_cents\":350}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false},\"expected\":{\"total_cents\":10000}},{\"input\":{\"lines\":[],\"member\":true},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":0,\"quantity\":7}],\"member\":true},\"expected\":{\"total_cents\":0}}]},{\"candidate\":\"willow\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":125,\"quantity\":3},{\"unit_cents\":7,\"quantity\":2}],\"member\":true},\"expected\":{\"total_cents\":350}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false},\"expected\":{\"total_cents\":10000}},{\"input\":{\"lines\":[],\"member\":true},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":0,\"quantity\":7}],\"member\":true},\"expected\":{\"total_cents\":0}}]}]}")

def main():
    candidates = json.loads((REPO / "candidates.json").read_text())["candidates"]
    assert set(candidates) == {row["candidate"] for row in REPORT["reviews"]}
    APP.mkdir(parents=True, exist_ok=True)
    (APP / "review.json").write_text(json.dumps(REPORT, ensure_ascii=False, allow_nan=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()

